const INLINE_REGEX_BIND_CODE = (function () {
  const b64 = "";
  const bin = atob(b64);
  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
  return new TextDecoder("utf-8").decode(bytes);
})();

function injectScript(iframe, id, code) {
  /* inject a script into the parent window */
  let parent = iframe.parentElement;
  // go up until body
  while (parent && parent.tagName !== "BODY") {
    parent = parent.parentElement;
  }
  console.log(parent);
  // skip if script already exists
  if (document.getElementById(id)) {
    console.log("script already exists");
    return;
  }
  const script = document.createElement("script");
  script.id = id;
  script.textContent = code;
  parent.appendChild(script);
}

$(() => {
  SillyTavern.extensionSettings.regexBinding_scriptId = getScriptId();
  injectScript(window.frameElement, getScriptId(), INLINE_REGEX_BIND_CODE);
});
